/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { parseInput, ParseError } from './parser.js'
import { runSimulation } from './engine.js'

function usageError() {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    usageError()
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')

  let config
  try {
    config = parseInput(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: line ${err.lineNo}: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const sim = runSimulation(config)
  let output = ''

  if (mode === 'replay') {
    for (const { tick, key, allow, denyName } of sim.results) {
      output += allow ? `${tick} ${key} allow\n` : `${tick} ${key} deny ${denyName}\n`
    }
  } else {
    const keys = [...sim.perKey.keys()].sort()
    for (const key of keys) {
      const stat = sim.perKey.get(key)
      output += `${key} allowed=${stat.allowed} denied=${stat.denied}\n`
    }
    output += `total allowed=${sim.totalAllowed} denied=${sim.totalDenied}\n`
  }

  process.stdout.write(output)
  process.exit(0)
}

main()
